import sys, json, re, base64

# THE QUESTIONS OF A LIBRARIAN (librarian, GH #950). Every question arrives on
# `in_lib` and leaves as exactly one `answer`: hop `op`, `op_id`, `caller`
# mirrored, body `{ok: true, op, op_id, items, next, ...}` or `{ok: false, op,
# op_id, error: {code, message}}`. Every list is a page: `limit` 1 to 20
# (default 20, more is cut to 20), `cursor` the offset as text, `next` the
# cursor of the following page ('' at the end).
#
# `find {q, kind?, fmt?, under?}` reads the catalogue alone -- one full-text
# search over the path words, the names, the summary line and the tags of
# every living source -- and wakes no file. The question is cut by `terms()`
# (WORD FOR WORD the index's), each word an own quoted prefix literal, all of
# them required: `"`, `*`, `:`, `-`, `AND`, `OR`, `NEAR` in a question are
# words then, never syntax. Every hit says `why` it matched (`name`, `path`,
# `tag`, `text`) and carries a `score`: the best field each word hit (name 4,
# path 3, tag 2, text 1), plus the full-text rank folded into 0..1.
#
# `symbol {name}`, `related {addr, how}` ask the graph space, `tree {under,
# depth}` the file space -- one `pull` each, and the answer comes back on
# `in_pulled`. `tree` pages the file space's `entries` by path here, with the
# offset as its cursor like `find`: the file space's `list` answers up to two
# thousand rows at depth 3 and `./tools` cuts nothing. Nothing is parked: the question rides in its own `op_id`
# (`lib:g:<token>`, `lib:f:t:<token>`, the token the compact JSON of the
# question in base64url), so an answer that never comes leaves no row behind,
# and the question is answered from what the answer carries -- symbol and
# related once more through the catalogue, for the path and summary line of
# every address. An error of the graph or the file space is handed on as it
# came (`ok: false` with its `error`).
#
# Refusals: `invalid_input` (an argument missing or wrong), `unknown_op`,
# `store_error`. No model, no network.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}


def _int(key, default):
    v = P.get(key, default)
    if v is None or (isinstance(v, str) and not v.strip()):
        return default
    try:
        return int(float(v))
    except Exception:
        return default


SCAN = max(20, _int("scan_max", 2000))

ME = "query"
OPS = ("find", "symbol", "related", "tree")
LIMIT_DEFAULT = 20
LIMIT_MAX = 20
DEPTH_MAX = 3
NAME_MAX = 512
HOWS = ("callers", "dependents", "deps", "similar")
ADDR_RE = re.compile(r"^(fh|ob)-[0-9a-f]{12}(@[0-9a-f]{4,64})?(#\S{1,512})?$")
FIND_COLS = ["source", "path", "kind", "fmt", "oneline", "tags", "names", "pterms", "nterms"]
WEIGHTS = (("name", 4), ("path", 3), ("tag", 2), ("text", 1))


# ============================================================ PURE: WORDS

RUN_RE = re.compile(r"[^\W_]+")


def split_case(run):
    """One word run cut at its case boundaries: a lower (or a digit) before an
    upper (`fooBar`, `utf8Decode`), and the last upper of an upper run before
    a lower (`HTTPServer`). Digits stay with the word they follow."""
    out, cur = [], ""
    for i, ch in enumerate(run):
        if cur and ch.isupper():
            prev = run[i - 1]
            nxt = run[i + 1] if i + 1 < len(run) else ""
            if not prev.isupper() or nxt.islower():
                out.append(cur)
                cur = ""
        cur += ch
    if cur:
        out.append(cur)
    return out


def terms(text):
    """The words of a text, lower case, in order, each once: every word run
    (`[^\\W_]+`, unicode) and, when it falls into more than one part at its
    case boundaries, the whole run first (`fooBar` -> foobar, foo, bar)."""
    out, seen = [], set()
    for run in RUN_RE.findall(str(text or "")):
        parts = split_case(run)
        toks = ([run] if len(parts) > 1 else []) + parts
        for t in toks:
            t = t.lower()
            if t and t not in seen:
                seen.add(t)
                out.append(t)
    return out


def query_terms(text):
    """The words a question asks for: the parts of every run only, never the
    whole run beside them. The catalog holds both (`fooBar` -> foobar, foo,
    bar), so `fooBar` asked as foo AND bar finds `fooBar.py` and `foo_bar.py`
    alike; with the whole run in the AND, `foo_bar.py` (runs foo, bar) never
    matched it (GH #950)."""
    out, seen = [], set()
    for run in RUN_RE.findall(str(text or "")):
        for t in split_case(run):
            t = t.lower()
            if t and t not in seen:
                seen.add(t)
                out.append(t)
    return out

def match_of(tokens):
    """The full-text expression of a question: every word a quoted prefix
    literal, implicitly AND -- no word of a question is ever syntax."""
    return " ".join('"%s"*' % t.replace('"', '""') for t in tokens)


# ============================================================ PURE: SCORE

def hits(q, toks):
    """A word of the question hits a field when it is a prefix of one of the
    field's words, or one of them (three letters or more) is a prefix of it --
    the stemmed index finds `parsing` for `parser`, and so does `why`."""
    return any(f.startswith(q) or (len(f) >= 3 and q.startswith(f)) for f in toks)


def json_list(v):
    try:
        x = json.loads(v) if isinstance(v, str) else v
    except Exception:
        return []
    return [str(t) for t in x] if isinstance(x, list) else []


def fields_of(row):
    return {"name": str(row.get("nterms") or "").split(),
            "path": str(row.get("pterms") or "").split(),
            "tag": terms(" ".join(json_list(row.get("tags")))),
            "text": terms(row.get("oneline"))}


def why_score(tokens, fields, rank):
    """(`why`, `score`) of one hit: the fields any word hit, in the order
    name, path, tag, text; the sum over the words of the best weight each hit,
    plus b/(1+b) of the rank b = -bm25 (never below 0), to four places."""
    total, hit = 0, set()
    for q in tokens:
        best = 0
        for f, w in WEIGHTS:
            if hits(q, fields.get(f) or []):
                hit.add(f)
                best = max(best, w)
        total += best
    try:
        b = max(0.0, -float(rank))
    except Exception:
        b = 0.0
    return [f for f, _ in WEIGHTS if f in hit], round(total + b / (1.0 + b), 4)


def under_of(v):
    """`under` as a folder: '/' or a path without its trailing `/`; None when
    it is no absolute path."""
    if not isinstance(v, str) or not v.startswith("/"):
        return None
    return v.rstrip("/") or "/"


def is_under(path, under):
    return under == "/" or path == under or path.startswith(under + "/")


def find_items(rows, tokens, under):
    """Store rows -> the hits of `find`, best first: (-score, path, source)."""
    out = []
    for r in rows:
        path = str(r.get("path") or "")
        if not is_under(path, under):
            continue
        why, score = why_score(tokens, fields_of(r), r.get("rank"))
        out.append({"file": str(r.get("source") or ""), "path": path,
                    "kind": str(r.get("kind") or ""), "fmt": str(r.get("fmt") or ""),
                    "oneline": str(r.get("oneline") or ""), "score": score, "why": why})
    out.sort(key=lambda x: (-x["score"], x["path"], x["file"]))
    return out


def page(items, cursor, limit):
    """One page of an ordered list: (items, next). The cursor is the offset
    of the page as text."""
    start = int(cursor or 0)
    chunk = items[start:start + limit]
    return chunk, (str(start + limit) if start + limit < len(items) else "")


def source_of(addr):
    """`fh-…@v#anchor` -> `fh-…`."""
    return str(addr or "").split("#", 1)[0].split("@", 1)[0]


def enrich(items, rows):
    """Graph items + `path` and `oneline` from the catalogue ('' for a source
    it does not know or holds as a grave); the graph's own fields stay."""
    by = {str(r.get("source") or ""): r for r in rows if not r.get("tomb")}
    out = []
    for it in items:
        if not isinstance(it, dict):
            continue
        row = by.get(source_of(it.get("addr"))) or {}
        x = dict(it)
        x["path"] = str(row.get("path") or "")
        x["oneline"] = str(row.get("oneline") or "")
        out.append(x)
    return out


def token_of(R):
    raw = json.dumps(R, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def question_of(token):
    """A token -> the question it carries, or None."""
    try:
        t = str(token or "")
        R = json.loads(base64.urlsafe_b64decode(t + "=" * (-len(t) % 4)).decode("utf-8"))
    except Exception:
        return None
    if not isinstance(R, dict) or R.get("op") not in OPS or not R.get("op_id") \
            or not isinstance(R.get("args"), dict):
        return None
    return R


def parse_pulled(op_id):
    """`lib:g:<token>` / `lib:f:t:<token>` -> (kind, question), or None."""
    s = str(op_id or "")
    for prefix, kind in (("lib:g:", "graph"), ("lib:f:t:", "tree")):
        if s.startswith(prefix):
            R = question_of(s[len(prefix):])
            return (kind, R) if R else None
    return None


class Bad(Exception):
    pass


def _whole(v, what, lo, hi):
    """An integer argument within lo..hi; a number written as text counts."""
    if isinstance(v, bool):
        raise Bad("`%s` is a whole number" % what)
    try:
        n = int(v) if not isinstance(v, float) or v.is_integer() else None
    except Exception:
        n = None
    if n is None or n < lo or (hi is not None and n > hi):
        raise Bad("`%s` is a whole number from %d%s" % (what, lo, " to %d" % hi if hi else ""))
    return n


def validate(op, a):
    """The arguments of a question, checked and normalised: (args, limit).
    Raises Bad with the message of an `invalid_input`."""
    limit = LIMIT_DEFAULT
    if a.get("limit") is not None:
        limit = min(LIMIT_MAX, _whole(a.get("limit"), "limit", 1, None))
    cur = a.get("cursor")
    out = {}
    if cur is not None and cur != "":
        if not isinstance(cur, (str, int)) or isinstance(cur, bool):
            raise Bad("`cursor` is the `next` of the page before")
        out["cursor"] = str(cur)
    if op == "find":
        q = a.get("q")
        if not isinstance(q, str) or not q.strip():
            raise Bad("find takes `q`, the words to look for")
        out["q"] = q
        for k in ("kind", "fmt"):
            if a.get(k) is not None:
                if not isinstance(a.get(k), str):
                    raise Bad("`%s` is text" % k)
                if a.get(k):
                    out[k] = a.get(k)
        if a.get("under") is not None:
            u = under_of(a.get("under"))
            if u is None:
                raise Bad("`under` is a folder starting with `/`")
            out["under"] = u
        if "cursor" in out and not out["cursor"].isdigit():
            raise Bad("`cursor` is the `next` of the page before")
    elif op == "symbol":
        name = a.get("name")
        if not isinstance(name, str) or not name.strip() or len(name) > NAME_MAX:
            raise Bad("symbol takes `name`, at most %d characters" % NAME_MAX)
        out["name"] = name.strip()
    elif op == "related":
        addr, how = a.get("addr"), a.get("how")
        if how not in HOWS:
            raise Bad("`how` is one of " + ", ".join(HOWS))
        if not isinstance(addr, str) or not ADDR_RE.match(addr.strip()):
            raise Bad("`addr` is fh-<12 hex>[@<version>][#<anchor>]")
        out["addr"], out["how"] = addr.strip(), how
        if how == "dependents" and a.get("depth") is not None:
            out["depth"] = _whole(a.get("depth"), "depth", 1, DEPTH_MAX)
    elif op == "tree":
        u = under_of(a.get("under") if a.get("under") is not None else "/")
        if u is None:
            raise Bad("`under` is a folder starting with `/`")
        out["under"] = u
        out["depth"] = 1 if a.get("depth") is None else _whole(a.get("depth"), "depth", 1,
                                                                 DEPTH_MAX)
        if "cursor" in out and not out["cursor"].isdigit():
            raise Bad("`cursor` is the `next` of the page before")
    return out, limit


def pull_of(R):
    """The one request a graph or tree question sends: (hop, body)."""
    a = R["args"]
    if R["op"] == "tree":
        return ({"route": "pull", "op": "list", "op_id": "lib:f:t:" + token_of(R)},
                {"op": "list", "args": {"prefix": a["under"], "depth": a["depth"]}})
    gop = "resolve" if R["op"] == "symbol" else a["how"]
    args = {"limit": R["limit"]}
    for k in (("name",) if R["op"] == "symbol" else ("addr", "depth")):
        if k in a:
            args[k] = a[k]
    if a.get("cursor"):
        args["cursor"] = a["cursor"]
    return ({"route": "pull", "op": gop, "op_id": "lib:g:" + token_of(R)},
            {"op": gop, "args": args})


def find_ops(R):
    a = R["args"]
    where = {"tomb": ""}
    for k in ("kind", "fmt"):
        if a.get(k):
            where[k] = a[k]
    if a.get("under") and a["under"] != "/":
        where["path"] = {"gte": a["under"]}
    return [("hits", {"operation": "search", "table": "entries",
                      "match": match_of(query_terms(a["q"])), "columns": FIND_COLS,
                      "where": where, "limit": SCAN})]


def enrich_ops(sources):
    return [("rows", {"operation": "select", "table": "entries",
                      "columns": ["source", "path", "oneline", "kind", "tomb"],
                      "where": {"source": {"in": sources}}, "limit": max(1, len(sources))})]


# ============================================================ PLUMBING

def emit(msgs):
    for m in msgs:
        if isinstance(m, dict) and not any(k in m for k in ("messages", "system", "attachments")):
            m["messages"] = []
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("librarian/query: %s\n" % reason)
    emit([])


def store(ops, phase, carry):
    return {"header": {"route": "query_store", "phase": phase, "reply_cell": ME,
                       "cur_call": json.dumps(carry, sort_keys=True)},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def finish(R, body):
    msg = {"header": {"route": "answer", "op": R["op"], "op_id": R["op_id"],
                      "caller": R.get("caller", "")},
           "messages": [], "op": R["op"], "op_id": R["op_id"]}
    msg.update(body)
    emit([msg])


def fail(R, code, message):
    finish(R, {"ok": False, "error": {"code": code, "message": message}})


def passed_on(R, ans):
    """An error of the graph or the file space, handed on as it came."""
    err = ans.get("error") if isinstance(ans.get("error"), dict) else {
        "code": "store_error", "message": "the answer carried no result"}
    finish(R, {"ok": False, "error": err})


def legs(body):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": ""}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": ""})
                leg["error_code"] = str(r.get("error_code") or "")
    elif len(out) == 1:
        next(iter(out.values()))["error_code"] = str(hop.get("error_code") or "")
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return [r for r in p if isinstance(r, dict)] if isinstance(p, list) else []


def graph_done(R, items, nxt, rs):
    body = {"ok": True, "items": enrich(items, rs), "next": nxt}
    if R["op"] == "related":
        body.update({"addr": R["args"]["addr"], "how": R["args"]["how"]})
    finish(R, body)


# ============================================================ LANES

lane = str(hop.get("route") or "")
op_ = str(hop.get("operation") or "")

if lane == "in_lib":
    op = str(hop.get("op") or d.get("op") or "")
    a = d.get("args") if isinstance(d.get("args"), dict) else {
        k: v for k, v in d.items() if k not in ("op", "op_id", "messages", "header")}
    R = {"op": op, "op_id": str(hop.get("op_id") or ""),
         "caller": str(hop.get("caller") or ""), "args": a, "limit": LIMIT_DEFAULT}
    if not R["op_id"]:
        fail(R, "invalid_input", "a question carries hop.op_id")
    if op not in OPS:
        fail(R, "unknown_op", "this lane serves " + ", ".join(OPS))
    try:
        R["args"], R["limit"] = validate(op, a)
    except Bad as e:
        fail(R, "invalid_input", str(e))
    if op == "find":
        if not query_terms(R["args"]["q"]):
            finish(R, {"ok": True, "items": [], "next": ""})
        emit([store(find_ops(R), "find", {"R": R})])
    h, b = pull_of(R)
    b["header"] = h
    emit([b])

if lane == "in_pulled":
    got = parse_pulled(hop.get("op_id"))
    if not got:
        park("in_pulled under a foreign or broken op_id %r -- dropped"
             % str(hop.get("op_id") or ""))
    kind, R = got
    if d.get("ok") is not True:
        passed_on(R, d)
    if kind == "tree":
        # A page of at most 20 entries, ordered by path, like every list here
        # (GH #950 section 3): unpaged, one `lib_tree {depth: 3}` handed up to
        # LIST_SCAN (2000) rows of the file space into a model's turn.
        a = R["args"]
        got = d.get("entries") if isinstance(d.get("entries"), list) else []
        got = sorted((e for e in got if isinstance(e, dict)),
                     key=lambda e: str(e.get("path") or ""))
        chunk, nxt = page(got, a.get("cursor"),
                          min(LIMIT_MAX, int(R.get("limit") or LIMIT_DEFAULT)))
        body = {"ok": True, "under": a["under"], "depth": a["depth"], "entries": chunk,
                "next": nxt}
        if d.get("more"):
            body["more"] = True
        finish(R, body)
    items = [x for x in (d.get("items") or []) if isinstance(x, dict)]
    nxt = str(d.get("next") or "")
    sources = sorted({source_of(x.get("addr")) for x in items} - {""})
    if not sources:
        graph_done(R, items, nxt, [])
    emit([store(enrich_ops(sources), "enrich", {"R": R, "items": items, "next": nxt})])

if lane:
    park("unknown lane %r -- dropped" % lane)
if not op_:
    park("a message with neither a lane nor a store answer -- dropped")

try:
    carry = json.loads(ctx.get("cur_call") or "null")
except Exception:
    carry = None
# The question of a store answer under a lower-case name: the locks load
# every upper-case assignment at the top of this program as its pure half,
# without a message (support/graph_space_pure.rs).
asked = carry.get("R") if isinstance(carry, dict) else None
if not isinstance(asked, dict) or not asked.get("op_id"):
    park("store answer without its question -- dropped")
lg = legs(d)
bad = sorted(c for c, leg in lg.items() if leg["error_code"])
if bad:
    sys.stderr.write("librarian/query: store refused %s\n" % ", ".join(bad))
    fail(asked, "store_error", "the catalogue refused a read; try again later")
phase = str(ctx.get("cur_phase") or "")
if phase == "find":
    rs = rows(lg, "hits")
    a = asked["args"]
    items = find_items(rs, query_terms(a["q"]), a.get("under") or "/")
    chunk, nxt = page(items, a.get("cursor"), asked["limit"])
    body = {"ok": True, "items": chunk, "next": nxt}
    if len(rs) >= SCAN:
        body["truncated"] = True
    finish(asked, body)
if phase == "enrich":
    graph_done(asked, carry.get("items") or [], str(carry.get("next") or ""), rows(lg, "rows"))
park("unknown phase %r -- dropped" % phase)
